use Kios\Infrastructure\{Database,MigrationRunner,StaffAccountService};
use Kios\MerchantOperations\{Inventory,StaffSessionIdentity};
$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$db=Database::connect();
function fingerprint(PDO $d):array{$out=[];foreach($d->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as $table){if(!preg_match('/^[a-z0-9_]+$/D',$table))throw new RuntimeException('Unexpected table');$rows=[];foreach($d->query('SELECT * FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC)as $r){$values=[];foreach($r as $k=>$v)$values[$k]=$v===null?'N':'V'.base64_encode((string)$v);$rows[]=json_encode($values,JSON_THROW_ON_ERROR);}sort($rows);$out[$table]=['rows'=>count($rows),'sha256'=>hash('sha256',implode("\n",$rows))];}ksort($out);return $out;}
if(($argv[3]??'')==='worker'){
 $a=$meta['merchants']['a'];$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$a['loginOutlet']]);$native=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($a['username'],$creds['owner_a_password'],'synthetic-concurrent');if(!$native)exit(2);$session=[];StaffAccountService::bind($session,$native);$session['_merchant_login_outlet']=$a['loginOutlet'];$s=new Inventory($db,new StaffSessionIdentity($db,static fn()=>$session,getenv('KIOS_MERCHANT_AUTH_RATE_KEY')));$s->act($a['merchant'],$a['outlet'],$argv[4],'receipt',['item'=>$argv[5],'quantity'=>'1','reason'=>'Concurrent synthetic receipt']);exit(0);
}
$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function test(string $name,callable $f):void{global $r;try{$f();$r['passed']++;$r['cases'][$name]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$name]=get_class($e).':'.$e->getMessage();}}
function check(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
test('Actual concurrent distinct and duplicate receipts serialize safely',function()use($db,$meta,$argv,&$r){$a=$meta['merchants']['a'];$q=$db->prepare('SELECT item_id,balance_milli FROM merchant_inventory_items WHERE merchant_id=? AND outlet_id=? ORDER BY name LIMIT 1');$q->execute([$a['merchant'],$a['outlet']]);$i=$q->fetch(PDO::FETCH_ASSOC);check((bool)$i);$before=(int)$i['balance_milli'];foreach([false,true]as $duplicate){$request=bin2hex(random_bytes(16));$children=[];for($n=0;$n<2;$n++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],'worker',$duplicate?$request:bin2hex(random_bytes(16)),$i['item_id']],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);check(is_resource($p));fclose($pipes[0]);$children[]=[$p,$pipes];}foreach($children as [$p,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$r['workers'][]=['exit'=>$exit,'stdout'=>$stdout,'stderr'=>$stderr];if($exit!==0)throw new RuntimeException('Worker exit '. $exit);}}$q->execute([$a['merchant'],$a['outlet']]);$after=$q->fetch(PDO::FETCH_ASSOC);$r['concurrentBalances']=['before'=>$before,'after'=>(int)$after['balance_milli'],'expected'=>$before+3000];check((int)$after['balance_milli']===$before+3000);});
