 if(getenv('USERNAME')!=='WDAGUtilityAccount'||getenv('KIOS_DB_HOST')!=='127.0.0.1'||getenv('KIOS_DB_PORT')!=='33081')throw new RuntimeException('Guest recovery boundary required');
 $root=new PDO('mysql:host=127.0.0.1;port=33081;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$root->exec('CREATE DATABASE kios_inventory_recovery');
 $dump='C:/KiosB0/inventory-recovery.sql';$pipes=[];$p=proc_open(['C:/Mapped/Tools/mariadb/bin/mysqldump.exe','--no-defaults','--host=127.0.0.1','--port=33081','--user=root','--single-transaction','--hex-blob','--routines','--triggers','kios_development'],[0=>['pipe','r'],1=>['file',$dump,'wb'],2=>['pipe','w']],$pipes);check(is_resource($p));fclose($pipes[0]);stream_get_contents($pipes[2]);fclose($pipes[2]);check(proc_close($p)===0);
 $pipes=[];$p=proc_open(['C:/Mapped/Tools/mariadb/bin/mysql.exe','--no-defaults','--host=127.0.0.1','--port=33081','--user=root','kios_inventory_recovery'],[0=>['file',$dump,'rb'],1=>['pipe','w'],2=>['pipe','w']],$pipes);check(is_resource($p));stream_get_contents($pipes[1]);stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($p)===0);
 $restored=new PDO('mysql:host=127.0.0.1;port=33081;dbname=kios_inventory_recovery;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$before=fingerprint($db);check(fingerprint($restored)===$before);check((new MigrationRunner($restored))->apply(dirname(__DIR__,2).'/database/migrations')===[]);$r['recovery']=['tables'=>count($before),'rowFingerprints'=>$before,'dumpSha256'=>hash_file('sha256',$dump),'migrationReplay'=>'NO-OP'];
});
file_put_contents($argv[3],json_encode($r,JSON_PRETTY_PRINT));echo json_encode(['passed'=>$r['passed'],'failed'=>$r['failed']]);exit($r['failed']?1:0);
